//! Differential test against `d3-hierarchy` 3.1.2, the layout library Mermaid 12.3.0's
//! treemap renderer uses.
//!
//! Every fixture under `testdata/` holds one tree and the exact rectangles
//! `hierarchy(root).sum(...).sort(...)` plus `treemap()` produced for it, generated by
//! `testdata/generate.mjs` against the copy under
//! `research/mermaid-port/upstream/mermaid/node_modules/.pnpm/d3-hierarchy@3.1.2`.
//!
//! The fixtures cover a flat tree, a wide flat tree, two and three levels, zero values
//! (including a zero total), all the tiling methods on the same tree (`squarify` with its
//! ratio, `binary`, `dice`, `slice`, `sliceDice`, `resquarify` with its ratio), Mermaid's
//! section padding functions with rounding, and constant inner and outer padding.
//! Rectangles and values are compared within `1e-6`. JSON has no NaN, so `JSON.stringify`
//! writes one as `null`; the test requires the port to produce a NaN there too.

use std::collections::HashSet;
use std::fs;
use std::path::PathBuf;

use serde::{Deserialize, Deserializer};

use super::treemap::{Padding, Tile, Treemap};
use super::{Hierarchy, Node, NodeId};

const TOLERANCE: f64 = 1e-6;

/// One tree node in a fixture and in the hierarchy under test.
#[derive(Clone, Debug, PartialEq)]
struct TestNode {
    name: String,
    value: Option<f64>,
    children: Option<Vec<TestNode>>,
}

#[derive(Deserialize)]
struct Fixture {
    name: String,
    size: [f64; 2],
    tile: String,
    ratio: Option<f64>,
    #[serde(default)]
    round: bool,
    #[serde(default)]
    padding: PaddingSpecs,
    tree: TreeSpec,
    output: Vec<OutputNode>,
}

#[derive(Deserialize)]
struct TreeSpec {
    name: String,
    value: Option<f64>,
    #[serde(default)]
    children: Vec<TreeSpec>,
}

#[derive(Deserialize, Default)]
struct PaddingSpecs {
    #[serde(default)]
    inner: PaddingSpec,
    #[serde(default)]
    top: PaddingSpec,
    #[serde(default)]
    right: PaddingSpec,
    #[serde(default)]
    bottom: PaddingSpec,
    #[serde(default)]
    left: PaddingSpec,
}

/// A padding as `generate.mjs` writes it: a number, or a pair chosen by whether the node has
/// children (Mermaid's `d.children && d.children.length > 0`).
#[derive(Deserialize)]
#[serde(untagged)]
enum PaddingSpec {
    Constant(f64),
    IfChildren { if_children: [f64; 2] },
}

impl Default for PaddingSpec {
    fn default() -> Self {
        Self::Constant(0.0)
    }
}

#[derive(Deserialize)]
struct OutputNode {
    path: String,
    name: String,
    depth: usize,
    #[serde(deserialize_with = "number")]
    value: f64,
    #[serde(deserialize_with = "number")]
    x0: f64,
    #[serde(deserialize_with = "number")]
    y0: f64,
    #[serde(deserialize_with = "number")]
    x1: f64,
    #[serde(deserialize_with = "number")]
    y1: f64,
}

/// Reads a number, turning JSON's `null` (a NaN written by `JSON.stringify`) into a NaN.
fn number<'de, D>(deserializer: D) -> Result<f64, D::Error>
where
    D: Deserializer<'de>,
{
    Ok(Option::<f64>::deserialize(deserializer)?.unwrap_or(f64::NAN))
}

fn fixture_path(name: &str) -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("src/layout/hierarchy/testdata")
        .join(name)
}

fn fixtures() -> Vec<String> {
    let mut names: Vec<String> = fs::read_dir(fixture_path(""))
        .expect("the testdata directory exists")
        .filter_map(Result::ok)
        .filter_map(|entry| {
            let name = entry.file_name().into_string().ok()?;
            name.ends_with(".json").then_some(name)
        })
        .collect();
    names.sort();
    names
}

fn test_node(spec: &TreeSpec) -> TestNode {
    TestNode {
        name: spec.name.clone(),
        value: spec.value,
        children: (!spec.children.is_empty())
            .then(|| spec.children.iter().map(test_node).collect::<Vec<_>>()),
    }
}

fn padding(spec: &PaddingSpec) -> Padding<TestNode> {
    match spec {
        PaddingSpec::Constant(value) => Padding::constant(*value),
        PaddingSpec::IfChildren { if_children } => {
            let [when_children, otherwise] = *if_children;
            Padding::function(move |node: &Node<TestNode>| {
                if node
                    .children
                    .as_ref()
                    .is_some_and(|children| !children.is_empty())
                {
                    when_children
                } else {
                    otherwise
                }
            })
        }
    }
}

impl Fixture {
    fn treemap(&self) -> Treemap<TestNode> {
        let mut treemap = Treemap::new()
            .size(self.size[0], self.size[1])
            .padding_inner(padding(&self.padding.inner))
            .padding_top(padding(&self.padding.top))
            .padding_right(padding(&self.padding.right))
            .padding_bottom(padding(&self.padding.bottom))
            .padding_left(padding(&self.padding.left))
            .round(self.round);
        let ratio = self.ratio.unwrap_or(1.0);
        treemap = match self.tile.as_str() {
            "squarify" => treemap.tile(Tile::Squarify),
            "squarify-ratio" => treemap.tile(Tile::squarify_ratio(ratio)),
            "binary" => treemap.tile(Tile::Binary),
            "dice" => treemap.tile(Tile::Dice),
            "slice" => treemap.tile(Tile::Slice),
            "sliceDice" => treemap.tile(Tile::SliceDice),
            "resquarify" => treemap.tile(Tile::Resquarify),
            "resquarify-ratio" => treemap.tile(Tile::resquarify_ratio(ratio)),
            other => panic!("{}: unknown tile {other}", self.name),
        };
        treemap
    }
}

fn close(actual: f64, expected: f64, context: &str) {
    if expected.is_nan() {
        assert!(actual.is_nan(), "{context}: expected NaN, got {actual}");
        return;
    }
    assert!(
        (actual - expected).abs() <= TOLERANCE,
        "{context}: expected {expected}, got {actual}"
    );
}

/// The path `generate.mjs` assigns: the child indices from the root, joined with `.`.
fn path_of(hierarchy: &Hierarchy<TestNode>, mut id: NodeId) -> String {
    let mut parts = Vec::new();
    while let Some(parent) = hierarchy.node(id).parent {
        let children = hierarchy
            .node(parent)
            .children
            .as_ref()
            .expect("a parent has children");
        let index = children
            .iter()
            .position(|&child| child == id)
            .expect("a parent lists its child");
        parts.push(index.to_string());
        id = parent;
    }
    parts.reverse();
    parts.join(".")
}

#[test]
fn matches_d3_hierarchy_treemap() {
    let names = fixtures();
    assert!(names.len() >= 6, "the fixtures cover at least 6 trees");
    let mut tiles = HashSet::new();

    for file in names {
        let text = fs::read_to_string(fixture_path(&file)).expect("the fixture is readable");
        let fixture: Fixture = serde_json::from_str(&text).expect("the fixture parses");
        let context = &fixture.name;
        tiles.insert(fixture.tile.clone());

        let mut hierarchy =
            Hierarchy::build(test_node(&fixture.tree), |node| node.children.clone());
        hierarchy.sum(|node| node.value);
        hierarchy.sort_by(|a, b| {
            (b.value.unwrap_or(0.0))
                .partial_cmp(&a.value.unwrap_or(0.0))
                .unwrap_or(std::cmp::Ordering::Equal)
        });
        fixture.treemap().layout(&mut hierarchy);

        assert_eq!(
            hierarchy.len(),
            fixture.output.len(),
            "{context}: node count"
        );

        for expected in &fixture.output {
            let id = hierarchy
                .descendants()
                .into_iter()
                .find(|&id| path_of(&hierarchy, id) == expected.path)
                .unwrap_or_else(|| panic!("{context}: missing node at path {:?}", expected.path));
            let node = hierarchy.node(id);
            assert_eq!(node.data.name, expected.name, "{context}: node name");
            assert_eq!(node.depth, expected.depth, "{context}: node depth");
            close(
                node.value.unwrap_or(f64::NAN),
                expected.value,
                &format!("{context}: {} value", expected.path),
            );
            close(
                node.x0,
                expected.x0,
                &format!("{context}: {} x0", expected.path),
            );
            close(
                node.y0,
                expected.y0,
                &format!("{context}: {} y0", expected.path),
            );
            close(
                node.x1,
                expected.x1,
                &format!("{context}: {} x1", expected.path),
            );
            close(
                node.y1,
                expected.y1,
                &format!("{context}: {} y1", expected.path),
            );
        }
    }

    for tile in [
        "squarify",
        "squarify-ratio",
        "binary",
        "dice",
        "slice",
        "sliceDice",
        "resquarify",
        "resquarify-ratio",
    ] {
        assert!(tiles.contains(tile), "the fixtures cover the {tile} tile");
    }
}
